const body = $input.first().json.body ?? $input.first().json;
const text = (body.text ?? '').toString();
if (!text.trim()) throw new Error('empty_selection');
const paragraph = (body.paragraph_context ?? '').toString();
const voiceId = body.voice_template_id ?? null;
const intensity = body.intensity === 'aggressive' ? 'aggressive' : 'editor';
const beforeWords = text.trim().split(/\s+/).filter(Boolean).length;
return [{ json: { text, paragraph, voice_id: voiceId, intensity, before_words: beforeWords } }];

// Compose the system prompt. Falls back to a sensible default voice when no template found.
const voice = $input.first().json;
const ctx = $('parse').first().json;
const tone = voice?.tone || 'plainspoken, slightly skeptical of hype';
const style = voice?.writing_style || 'short opening sentence, concrete numbers, no filler adjectives';
const banned = Array.isArray(voice?.banned_words) ? voice.banned_words.join(', ') : 'easy, simple, just, leverage, unlock, synergy';
const aggressive = ctx.intensity === 'aggressive';
const targetWords = aggressive ? Math.max(8, Math.round(ctx.before_words * 0.7)) : Math.max(8, Math.round(ctx.before_words * 0.9));
const system = `You tighten prose without changing meaning, while preserving an author's voice.

Voice tone: ${tone}
Writing style: ${style}
Banned words (never include in output): ${banned}

Rules:
- Output ONLY the rewritten text, no preface, no quotes.
- Target roughly ${targetWords} words (currently ${ctx.before_words}).
- Drop filler adjectives, adverbs, redundant connectors.
- Keep technical terms exact.
- Keep the original sentence structure when it serves the rhythm.
- Never invent facts the original didn't contain.`;
return [{ json: { ...ctx, system_prompt: system } }];

