let text = $input.first().json.message ?? $input.first().json.text ?? $input.first().json.content ?? '';
text = text.trim();
// Strip leading/trailing quotes some models add despite instructions.
text = text.replace(/^['\"\u201C]+|['\"\u201D]+$/g, '');
const beforeWords = $('parse').first().json.before_words;
const afterWords = text.split(/\s+/).filter(Boolean).length;
return [{ json: {
  text,
  before_words: beforeWords,
  after_words: afterWords,
  diff_summary: `${beforeWords} → ${afterWords} words (${Math.round((1 - afterWords/Math.max(beforeWords,1)) * 100)}% tighter)`,
} }];
